mapper.select:
SELECT x.campaign_id AS "id", SUM(x.impressions) AS "impressions", SUM(x.clicks) AS "clicks", SUM(x.spend) AS "spend",
       SUM(x.sales) AS "sales", SUM(x.orders) AS "orders"
FROM (
    SELECT st.campaign_id, st.impressions, st.clicks, st.spend, st.sales, st.orders
    FROM ecom_ad_stat st
    WHERE st.level = 'CAMPAIGN' AND st.stat_date >= #{begin} AND st.stat_date <= #{end}

    AND st.campaign_id = #{campaignId}
    UNION ALL
    SELECT d.campaign_id, d.impressions, d.clicks, d.spend, d.ad_sales AS sales, d.ad_orders AS orders
    FROM ecom_ad_daily d
    WHERE d.campaign_id IS NOT NULL AND d.ad_date >= #{begin} AND d.ad_date <= #{end}

    AND d.campaign_id = #{campaignId}
      AND NOT EXISTS (SELECT 1 FROM ecom_ad_stat s2 WHERE s2.level = 'CAMPAIGN' AND s2.entity_id = d.campaign_id AND s2.stat_date = d.ad_date)
) x
GROUP BY x.campaign_id

SELECT x.ad_group_id AS "id", SUM(x.impressions) AS "impressions", SUM(x.clicks) AS "clicks", SUM(x.spend) AS "spend",
       SUM(x.sales) AS "sales", SUM(x.orders) AS "orders"
FROM (
    SELECT st.ad_group_id, st.impressions, st.clicks, st.spend, st.sales, st.orders
    FROM ecom_ad_stat st
    WHERE st.level = 'TARGET' AND st.ad_group_id IS NOT NULL AND st.stat_date >= #{begin} AND st.stat_date <= #{end}

    AND st.campaign_id = #{campaignId}
    UNION ALL
    SELECT d.ad_group_id, d.impressions, d.clicks, d.spend, d.ad_sales AS sales, d.ad_orders AS orders
    FROM ecom_ad_daily d
    WHERE d.ad_group_id IS NOT NULL AND d.ad_date >= #{begin} AND d.ad_date <= #{end}

    AND d.campaign_id = #{campaignId}
      AND NOT EXISTS (SELECT 1 FROM ecom_ad_stat s2 WHERE s2.level = 'TARGET' AND s2.ad_group_id = d.ad_group_id AND s2.stat_date = d.ad_date)
) x
GROUP BY x.ad_group_id

SELECT st.entity_id AS "id", SUM(st.impressions) AS "impressions", SUM(st.clicks) AS "clicks", SUM(st.spend) AS "spend",
       SUM(st.sales) AS "sales", SUM(st.orders) AS "orders"
FROM ecom_ad_stat st
WHERE st.level = 'TARGET' AND st.stat_date >= #{begin} AND st.stat_date <= #{end}

AND st.campaign_id = #{campaignId}
AND st.ad_group_id = #{adGroupId}
GROUP BY st.entity_id

SELECT t.store_id, s.name AS store_name, s.currency, t.campaign_id, c.name AS campaign_name, t.ad_group_id, g.name AS ad_group_name, t.keyword_text, t.match_type, t.search_term, SUM(t.impressions) AS impressions, SUM(t.clicks) AS clicks, SUM(t.spend) AS spend, SUM(t.sales) AS sales, SUM(t.orders) AS orders FROM ecom_ad_search_term t JOIN ecom_store s ON s.id = t.store_id JOIN ecom_ad_campaign c ON c.id = t.campaign_id LEFT JOIN ecom_ad_group g ON g.id = t.ad_group_id WHERE t.stat_date >= #{begin} AND t.stat_date <= #{end} AND t.store_id = #{storeId} AND t.campaign_id = #{campaignId}
AND (t.search_term LIKE CONCAT('%', #{keyword}, '%') OR t.keyword_text LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY t.store_id, s.name, s.currency, t.campaign_id, c.name, t.ad_group_id, g.name, t.keyword_text, t.match_type, t.search_term ORDER BY spend DESC LIMIT #{limit}

SELECT COUNT(*) FROM ecom_ad_rule_log l
WHERE l.status = 'PENDING'
AND l.store_id = #{storeId}
